EXTENSION_FILES = {
    "content.js": "const ZAIN_PAYMENT_URL = \"https://app.sa.zain.com/ar/contract-payment\";\nconst ZAIN_QUICKPAY_URL = \"https://app.sa.zain.com/ar/quickpay\";\nconst RESULT_TIMEOUT_MS = 60_000;\nconst RESULT_SETTLE_MS = 750;\nconst AMOUNT_STABILITY_MS = 500;\nconst UNCHANGED_AMOUNT_GRACE_MS = 4_000;\nconst ZERO_AMOUNT_GRACE_MS = 5_000;\nconst REDIRECT_GRACE_MS = 8_000;\n\nlet loopRunning = false;\n\nchrome.runtime.onMessage.addListener((message, sender, sendResponse) => {\n  if (message?.type === \"ping\") {\n    sendResponse({ status: \"ready\" });\n    return;\n  }\n  if (message?.type === \"wake\") {\n    startLoop();\n  }\n});\n\nconst contentMemoryStorage = {};\n\nasync function safeStorageGet(keys) {\n  const isArray = Array.isArray(keys);\n  const keyList = isArray ? keys : (typeof keys === \"string\" ? [keys] : Object.keys(keys || {}));\n  let result = {};\n  try {\n    result = await chrome.storage.local.get(keys);\n  } catch (error) {\n    console.warn(\"[ZainChecker:Content] Storage get failed, using memory:\", error);\n  }\n  for (const k of keyList) {\n    if (result[k] === undefined && contentMemoryStorage[k] !== undefined) {\n      result[k] = contentMemoryStorage[k];\n    }\n  }\n  return result;\n}\n\nasync function safeStorageSet(items) {\n  if (!items || typeof items !== \"object\") return;\n  Object.assign(contentMemoryStorage, items);\n  try {\n    await chrome.storage.local.set(items);\n  } catch (error) {\n    console.warn(\"[ZainChecker:Content] Storage set failed, retained in memory:\", error);\n  }\n}\n\nconsole.log(\"[ZainChecker:Content] Script loaded on:\", window.location.href);\ninitializeChecker();\n\nasync function initializeChecker() {\n  console.log(\"[ZainChecker:Content] initializeChecker starting on:\", window.location.href);\n  try {\n    await autoStartIfRequested();\n    await startLoop();\n  } catch (error) {\n    console.error(\"[ZainChecker:Content] initializeChecker error:\", error);\n    if (!isExtensionContextInvalidated(error)) {\n      try {\n        await safeStorageSet({\n          zainCheckerStatus: `Page error: ${String(error?.message || error)}`,\n        });\n      } catch (reportingError) {\n        if (!isExtensionContextInvalidated(reportingError)) throw reportingError;\n      }\n    }\n  }\n}\n\nasync function autoStartIfRequested() {\n  const pageUrl = new URL(window.location.href);\n  const recordType = pageUrl.pathname.endsWith(\"/contract-payment\")\n    ? \"account\"\n    : pageUrl.pathname.endsWith(\"/quickpay\")\n    ? \"wallet\"\n    : \"\";\n  if (!recordType) return;\n\n  const searchNumber = readPageSearchNumber(pageUrl, recordType);\n  if (!/^\\d+$/.test(searchNumber)) return;\n\n  const state = await safeStorageGet(\"zainCheckerRunning\");\n  console.log(\"[ZainChecker:Content] autoStartIfRequested: zainCheckerRunning =\", state.zainCheckerRunning, \"recordType =\", recordType, \"searchNumber =\", searchNumber);\n  if (state.zainCheckerRunning) {\n    try {\n      const res = await sendMessage({ type: \"adopt_tab\" });\n      console.log(\"[ZainChecker:Content] adopt_tab response:\", JSON.stringify(res));\n    } catch (e) {\n      console.warn(\"[ZainChecker:Content] adopt_tab non-fatal error:\", e);\n    }\n    return;\n  }\n\n  try {\n    const res = await sendMessage({\n      type: \"auto_start\",\n      record_type: recordType,\n      search_number: searchNumber,\n    });\n    console.log(\"[ZainChecker:Content] auto_start response:\", JSON.stringify(res));\n  } catch (e) {\n    console.warn(\"[ZainChecker:Content] auto_start non-fatal error:\", e);\n  }\n}\n\nasync function startLoop() {\n  if (loopRunning) {\n    console.log(\"[ZainChecker:Content] startLoop already running, skipping duplicate call.\");\n    return;\n  }\n  loopRunning = true;\n  console.log(\"[ZainChecker:Content] startLoop started.\");\n\n  try {\n    while (await shouldRun()) {\n      let task;\n      try {\n        task = await sendMessage({ type: \"poll_task\" });\n        console.log(\"[ZainChecker:Content] Polled task from SW:\", JSON.stringify(task));\n      } catch (sendError) {\n        if (isExtensionContextInvalidated(sendError)) {\n          console.warn(\"[ZainChecker:Content] Context invalidated, breaking loop.\");\n          break;\n        }\n        console.warn(\"[ZainChecker:Content] poll_task sendError:\", sendError);\n        await delay(1_000);\n        continue;\n      }\n\n      if (!task || typeof task !== \"object\") {\n        console.warn(\"[ZainChecker:Content] Received invalid task:\", task);\n        await delay(1_000);\n        continue;\n      }\n\n      if (task.status === \"check\") {\n        console.log(\"[ZainChecker:Content] Received task to check: row\", task.row_number, \"number\", task.search_number);\n        const navigationStarted = await processTask(task);\n        console.log(\"[ZainChecker:Content] processTask returned navigationStarted =\", navigationStarted);\n        if (navigationStarted) {\n          // Allow tab navigation/reload to initiate. If page reloads, this context terminates.\n          // If page stays active or in-page navigation occurs, keep the loop alive so it never hangs!\n          await delay(2_000);\n          continue;\n        }\n        continue;\n      }\n\n      if (task.status === \"complete\" || task.status === \"error\") {\n        console.log(\"[ZainChecker:Content] Loop terminating on status:\", task.status);\n        break;\n      }\n\n      if (task.status === \"inactive\") {\n        console.warn(\"[ZainChecker:Content] SW reported inactive, sending adopt_tab and retrying...\");\n        try {\n          await sendMessage({ type: \"adopt_tab\" });\n        } catch {}\n        await delay(1_000);\n        continue;\n      }\n\n      const retrySeconds = Number(task.retry_after_seconds ?? 2.5);\n      if (retrySeconds > 0) {\n        console.log(`[ZainChecker:Content] Task status \"${task.status}\". Waiting ${retrySeconds}s...`);\n        await delay(retrySeconds * 1_000);\n      }\n    }\n  } catch (error) {\n    console.error(\"[ZainChecker:Content] startLoop catch:\", error);\n    if (!isExtensionContextInvalidated(error)) {\n      try {\n        await safeStorageSet({\n          zainCheckerStatus: `Page error: ${String(error?.message || error)}`,\n        });\n      } catch (reportingError) {\n        if (!isExtensionContextInvalidated(reportingError)) throw reportingError;\n      }\n    }\n  } finally {\n    loopRunning = false;\n    console.log(\"[ZainChecker:Content] startLoop exited, loopRunning set to false.\");\n  }\n}\n\nasync function shouldRun() {\n  const state = await safeStorageGet(\"zainCheckerRunning\");\n  const running = Boolean(state.zainCheckerRunning);\n  console.log(\"[ZainChecker:Content] shouldRun check:\", running);\n  return running;\n}\n\nasync function processTask(task) {\n  const state = await safeStorageGet(\"zainCheckerActiveTask\");\n  let activeTask = state.zainCheckerActiveTask;\n  console.log(\"[ZainChecker:Content] processTask for\", task.search_number, \"activeTask was:\", JSON.stringify(activeTask), \"do_single_refresh:\", task.do_single_refresh);\n\n  if (task.do_single_refresh === true) {\n    console.log(\n      \"[ZainChecker:Content] Performing single one-time page refresh (1x only) for Service Number (2...) Cycle #\",\n      task.service_cycle_id,\n    );\n    activeTask = {\n      task_id: task.task_id,\n      row_number: task.row_number,\n      record_type: task.record_type,\n      search_number: task.search_number,\n      stage: \"navigating\",\n      previous_website_amount: \"\",\n    };\n    await safeStorageSet({ zainCheckerActiveTask: activeTask });\n    await navigateTask(task, \"\", true);\n    return true;\n  }\n\n  if (!sameTask(activeTask, task)) {\n    const isRequestedPage = isRequestedRecordPage(\n      task.record_type,\n      task.search_number,\n    );\n    console.log(\"[ZainChecker:Content] !sameTask. isRequestedPage for\", task.search_number, \"is:\", isRequestedPage);\n    activeTask = {\n      task_id: task.task_id,\n      row_number: task.row_number,\n      record_type: task.record_type,\n      search_number: task.search_number,\n      stage: \"navigating\",\n      previous_website_amount: isRequestedPage ? \"\" : readCustomAmount(),\n    };\n    await safeStorageSet({ zainCheckerActiveTask: activeTask });\n    if (!isRequestedPage) {\n      console.log(\"[ZainChecker:Content] Reusing same tab and navigating to:\", task.search_number);\n      await navigateTask(task, activeTask.previous_website_amount, false);\n      return true;\n    }\n  }\n\n  activeTask.stage = \"reading\";\n  await safeStorageSet({ zainCheckerActiveTask: activeTask });\n  console.log(\"[ZainChecker:Content] Calling waitForResult for\", task.search_number);\n  const result = await waitForResult(\n    task.record_type,\n    task.search_number,\n    activeTask.previous_website_amount,\n  );\n  console.log(\"[ZainChecker:Content] waitForResult result:\", JSON.stringify(result));\n  return submitResult(task, result);\n}\n\nasync function submitResult(task, result) {\n  await delay(700);\n  console.log(\"[ZainChecker:Content] submitResult for\", task.search_number, \"result:\", JSON.stringify(result));\n  const response = await sendMessage({\n    type: \"submit_result\",\n    result: {\n      task_id: task.task_id,\n      row_number: task.row_number,\n      contract: task.search_number,\n      record_type: task.record_type,\n      search_number: task.search_number,\n      ...result,\n    },\n  });\n  console.log(\"[ZainChecker:Content] submitResult response from SW:\", JSON.stringify(response));\n\n  if (\n    ![\n      \"waiting\",\n      \"recheck_mismatch\",\n      \"reload_mismatch\",\n      \"retry_redirect\",\n      \"network_wait\",\n      \"open_incognito\",\n      \"incognito_failed\",\n      \"complete\",\n      \"error\",\n    ].includes(response.status)\n  ) {\n    throw new Error(response.message || \"Python rejected the browser result.\");\n  }\n\n  if (response.status === \"reload_mismatch\") {\n    const retryTask = { ...task, task_id: response.task_id || task.task_id };\n    await safeStorageSet({\n      zainCheckerActiveTask: {\n        task_id: retryTask.task_id,\n        row_number: task.row_number,\n        record_type: task.record_type,\n        search_number: task.search_number,\n        stage: \"navigating\",\n        previous_website_amount: \"\",\n      },\n    });\n    const retrySeconds = Math.max(Number(response.retry_after_seconds || 1), 1);\n    await delay(retrySeconds * 1_000);\n    await navigateTask(retryTask, \"\", true);\n    return true;\n  }\n\n  if (response.status === \"retry_redirect\") {\n    const retryTask = { ...task, task_id: response.task_id || task.task_id };\n    await safeStorageSet({\n      zainCheckerActiveTask: {\n        task_id: retryTask.task_id,\n        row_number: task.row_number,\n        record_type: task.record_type,\n        search_number: task.search_number,\n        stage: \"navigating\",\n        previous_website_amount: \"\",\n      },\n    });\n    const retrySeconds = Math.max(Number(response.retry_after_seconds || 1), 1);\n    await delay(retrySeconds * 1_000);\n    await navigateTask(retryTask, \"\");\n    return true;\n  }\n\n  if (\n    response.status !== \"open_incognito\" &&\n    response.status !== \"incognito_failed\"\n  ) {\n    await safeStorageSet({ zainCheckerActiveTask: null });\n  }\n  return (\n    response.status === \"open_incognito\" ||\n    response.status === \"incognito_failed\"\n  );\n}\n\nasync function waitForResult(recordType, searchNumber, previousWebsiteAmount) {\n  const activeClock = createActiveClock();\n  const previousNormalized = normalizeAmountValue(previousWebsiteAmount);\n  let candidateNormalized = \"\";\n  let candidateSince = 0;\n  let wrongPageSince = 0;\n\n  try {\n    while (activeClock.elapsed() < RESULT_TIMEOUT_MS) {\n      const rejection = readRejection();\n      if (rejection) {\n        return {\n          ...rejection,\n          hidden_seconds: activeClock.hiddenMilliseconds() / 1_000,\n        };\n      }\n\n      const activeElapsed = activeClock.elapsed();\n      if (document.readyState === \"loading\") {\n        await waitForPageSignal(1_000);\n        continue;\n      }\n\n      if (!isRequestedRecordPage(recordType, searchNumber)) {\n        if (!wrongPageSince) wrongPageSince = activeElapsed;\n        if (activeElapsed - wrongPageSince >= REDIRECT_GRACE_MS) {\n          return {\n            status: \"redirected\",\n            current_url: window.location.href,\n            hidden_seconds: activeClock.hiddenMilliseconds() / 1_000,\n          };\n        }\n        await waitForPageSignal(1_000);\n        continue;\n      }\n      wrongPageSince = 0;\n\n      const result = readCurrentResult(recordType, searchNumber);\n      if (result && result.status !== \"ok\") {\n        return {\n          ...result,\n          hidden_seconds: activeClock.hiddenMilliseconds() / 1_000,\n        };\n      }\n\n      if (result?.status === \"ok\") {\n        const currentNormalized = normalizeAmountValue(result.website_amount);\n        if (currentNormalized !== candidateNormalized) {\n          candidateNormalized = currentNormalized;\n          candidateSince = activeElapsed;\n        }\n\n        const stableFor = activeElapsed - candidateSince;\n        const isPreviousValue = Boolean(\n          previousNormalized && currentNormalized === previousNormalized,\n        );\n        const isProvisionalZero = isZeroAmount(currentNormalized);\n        const requiredWait = Math.max(\n          AMOUNT_STABILITY_MS,\n          isPreviousValue ? UNCHANGED_AMOUNT_GRACE_MS : RESULT_SETTLE_MS,\n          isProvisionalZero ? ZERO_AMOUNT_GRACE_MS : 0,\n        );\n\n        if (stableFor >= requiredWait) {\n          return {\n            ...result,\n            provisional_zero: isProvisionalZero,\n            hidden_seconds: activeClock.hiddenMilliseconds() / 1_000,\n          };\n        }\n      }\n      await waitForPageSignal(1_000);\n    }\n  } finally {\n    activeClock.dispose();\n  }\n\n  return {\n    status: \"page_timeout\",\n    message: \"Zain did not show an amount before the timeout.\",\n    hidden_seconds: activeClock.hiddenMilliseconds() / 1_000,\n    debug: JSON.stringify({\n      hasIdentity: hasRequestedIdentity(recordType, searchNumber),\n      isRequestedPage: isRequestedRecordPage(recordType, searchNumber),\n      amountInputVisible: document.querySelector('#customAmount') ? isVisible(document.querySelector('#customAmount')) : false,\n      amountInputValue: document.querySelector('#customAmount') ? document.querySelector('#customAmount').value : 'null',\n      amountSpanVisible: document.querySelector('.quickpay__custom-balance-input span[aria-hidden=\"true\"]') ? isVisible(document.querySelector('.quickpay__custom-balance-input span[aria-hidden=\"true\"]')) : false,\n      amountSpanText: document.querySelector('.quickpay__custom-balance-input span[aria-hidden=\"true\"]') ? document.querySelector('.quickpay__custom-balance-input span[aria-hidden=\"true\"]').innerText : 'null'\n    })\n  };\n}\n\nasync function navigateTask(task, previousWebsiteAmount, reload = false) {\n  const directUrl = buildDirectUrl(task.record_type, task.search_number);\n  console.log(\"[ZainChecker:Content] navigateTask target:\", directUrl, \"currentUrl:\", window.location.href, \"reload:\", reload);\n  const response = await sendMessage({\n    type: \"navigate_task\",\n    task: {\n      task_id: task.task_id,\n      row_number: task.row_number,\n      record_type: task.record_type,\n      search_number: task.search_number,\n    },\n    previous_website_amount: previousWebsiteAmount,\n    reload,\n  });\n  console.log(\"[ZainChecker:Content] navigateTask response:\", JSON.stringify(response));\n  if (response?.status !== \"navigating\") {\n    throw new Error(response?.message || \"The extension could not navigate the checker tab.\");\n  }\n}\n\nfunction createActiveClock() {\n  const startedAt = Date.now();\n  let hiddenAt = document.hidden ? startedAt : 0;\n  let completedHiddenMilliseconds = 0;\n\n  const onVisibilityChange = () => {\n    const now = Date.now();\n    if (document.hidden && !hiddenAt) {\n      hiddenAt = now;\n    } else if (!document.hidden && hiddenAt) {\n      completedHiddenMilliseconds += now - hiddenAt;\n      hiddenAt = 0;\n    }\n  };\n  document.addEventListener(\"visibilitychange\", onVisibilityChange);\n\n  const hiddenMilliseconds = () =>\n    completedHiddenMilliseconds + (hiddenAt ? Date.now() - hiddenAt : 0);\n\n  return {\n    elapsed: () => Date.now() - startedAt,\n    hiddenMilliseconds,\n    dispose: () =>\n      document.removeEventListener(\"visibilitychange\", onVisibilityChange),\n  };\n}\n\nfunction waitForPageSignal(maximumWaitMilliseconds) {\n  return new Promise((resolve) => {\n    let settled = false;\n    const finish = () => {\n      if (settled) return;\n      settled = true;\n      clearTimeout(timer);\n      observer.disconnect();\n      document.removeEventListener(\"visibilitychange\", finish);\n      document.removeEventListener(\"DOMContentLoaded\", finish);\n      resolve();\n    };\n    const observer = new MutationObserver(finish);\n    if (document.documentElement) {\n      observer.observe(document.documentElement, {\n        subtree: true,\n        childList: true,\n        characterData: true,\n        attributes: true,\n        attributeFilter: [\"value\", \"class\", \"style\"],\n      });\n    } else {\n      document.addEventListener(\"DOMContentLoaded\", finish, { once: true });\n    }\n    document.addEventListener(\"visibilitychange\", finish);\n    const timer = setTimeout(finish, maximumWaitMilliseconds);\n  });\n}\n\nfunction isRequestedRecordPage(recordType, searchNumber) {\n  if (!isSupportedRecordType(recordType)) return false;\n  const pageUrl = new URL(window.location.href);\n  if (readPageSearchNumber(pageUrl, recordType) === String(searchNumber)) {\n    return true;\n  }\n  return (\n    recordType === \"wallet\" &&\n    isRequestedWalletContent(String(searchNumber))\n  );\n}\n\nfunction isRequestedWalletContent(searchNumber) {\n  const bodyText = normalizeDigits(String(document.body?.innerText || \"\"));\n  const hasQuickPayHeading =\n    bodyText.includes(\"الدفع السريع\") ||\n    /quick\\s*pay/i.test(bodyText);\n  const hasAmountHeading =\n    bodyText.includes(\"إجمالي المبلغ المطلوب\") ||\n    bodyText.includes(\"ادفع فاتورتك المتبقية\") ||\n    /total\\s+(?:required|due)\\s+amount|remaining\\s+bill/i.test(bodyText);\n  const escapedNumber = searchNumber.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const hasRequestedIdentity = new RegExp(\n    `${escapedNumber}\\\\s*\\\\|\\\\s*(?:مفوتر|postpaid)`,\n    \"i\",\n  ).test(bodyText);\n  return hasQuickPayHeading && hasAmountHeading && hasRequestedIdentity;\n}\n\nfunction readPageSearchNumber(pageUrl, recordType) {\n  if (recordType === \"account\") {\n    if (!pageUrl.pathname.endsWith(\"/contract-payment\")) return \"\";\n    return String(pageUrl.searchParams.get(\"contract\") || \"\").trim();\n  }\n  if (recordType === \"wallet\") {\n    if (!pageUrl.pathname.endsWith(\"/quickpay\")) return \"\";\n    return String(pageUrl.searchParams.get(\"account\") || \"\").trim();\n  }\n  return \"\";\n}\n\nfunction buildDirectUrl(recordType, searchNumber) {\n  const encoded = encodeURIComponent(searchNumber);\n  if (recordType === \"account\") {\n    return `${ZAIN_PAYMENT_URL}?contract=${encoded}`;\n  }\n  if (recordType === \"wallet\") {\n    return `${ZAIN_QUICKPAY_URL}?account=${encoded}`;\n  }\n  throw new Error(\"Python returned an unsupported record type.\");\n}\n\nfunction isSupportedRecordType(recordType) {\n  return recordType === \"account\" || recordType === \"wallet\";\n}\n\nfunction readCurrentResult(recordType, contract) {\n  const rejection = readRejection();\n  if (rejection) return rejection;\n\n  if (!hasRequestedIdentity(recordType, contract)) return null;\n\n  for (const selector of [\n    \"#customAmount\",\n    'input[name=\"customAmount\"]',\n    '#formSaveContractPaymentConfig input[name=\"amount\"]',\n    'input[name=\"amount\"]',\n  ]) {\n    for (const field of document.querySelectorAll(selector)) {\n      let value = String(field.value || \"\").trim();\n      \n      if (isVisible(field)) {\n        if (!value) {\n          const span = document.querySelector(\".quickpay__custom-balance-input\");\n          if (span) {\n            const spanText = String(span.innerText || \"\").trim();\n            if (spanText) {\n              value = spanText;\n            }\n          }\n        }\n        if (value) {\n          return { status: \"ok\", website_amount: value };\n        }\n      }\n    }\n  }\n\n  // Fallback for when Zain renders amount in span or container (e.g. 0.00 paid accounts or balance text)\n  for (const selector of [\n    \".quickpay__custom-balance-input\",\n    \".quickpay__custom-balance-input span\",\n    \"#payBillValue span\",\n    \"#payBillValue\",\n  ]) {\n    for (const field of document.querySelectorAll(selector)) {\n      const value = String(field.innerText || \"\").trim();\n      if (isVisible(field) && value) {\n        return { status: \"ok\", website_amount: value };\n      }\n    }\n  }\n\n  // This Zain page explicitly asks for a payment amount but displays no\n  // balance. Treat that confirmed empty state as zero after the normal\n  // stability guard, instead of scraping unrelated text from the page.\n  if (hasEmptyPaymentAmount(recordType)) {\n    return { status: \"ok\", website_amount: \"0.00\", empty_amount: true };\n  }\n\n  for (const selector of [\n    \"#formValidateContractPaymentInfo .invalid-feedback\",\n    \".alert-danger\",\n    \".text-danger\",\n  ]) {\n    for (const element of document.querySelectorAll(selector)) {\n      const text = String(element.innerText || \"\").trim();\n      if (isVisible(element) && text) {\n        return { status: \"error\", message: `Zain error: ${text}` };\n      }\n    }\n  }\n\n  const alertBox = document.querySelector(\".alert-danger\");\n  if (isVisible(alertBox) && alertBox.innerText.includes(\"غير متوفرة\")) {\n    return { status: \"website_error\", message: \"Service unavailable.\" };\n  }\n\n  return null;\n}\n\nfunction readCustomAmount() {\n  for (const selector of [\"#customAmount\", 'input[name=\"customAmount\"]']) {\n    for (const field of document.querySelectorAll(selector)) {\n      let value = String(field.value || \"\").trim();\n      \n      if (isVisible(field) && value) return value;\n    }\n  }\n  return \"\";\n}\n\nfunction hasEmptyPaymentAmount(recordType) {\n  const bodyText = normalizeDigits(String(document.body?.innerText || \"\"));\n  if (recordType === \"account\") {\n    return (\n      bodyText.includes(\"سداد المدفوعات المتأخرة\") ||\n      bodyText.includes(\"أدخل المبلغ المطلوب\") ||\n      bodyText.includes(\"أدخل المبلغ\") ||\n      bodyText.includes(\"لا توجد مبالغ مستحقة\") ||\n      bodyText.includes(\"المبلغ المراد دفعه\")\n    );\n  }\n  return (\n    (bodyText.includes(\"إجمالي المبلغ المطلوب\") &&\n      bodyText.includes(\"ادفع فاتورتك المتبقية\")) ||\n    bodyText.includes(\"لا توجد فواتير مستحقة\") ||\n    bodyText.includes(\"لا توجد مبالغ مستحقة\")\n  );\n}\n\nfunction normalizeAmountValue(value) {\n  return normalizeDigits(String(value || \"\"))\n    .replace(/[\\s٬,]/g, \"\")\n    .replace(\"٫\", \".\")\n    .trim();\n}\n\nfunction isZeroAmount(normalizedValue) {\n  return Boolean(normalizedValue) && /^0*(?:\\.0*)?$/.test(normalizedValue);\n}\n\nfunction hasRequestedIdentity(recordType, searchNumber) {\n  const expected = String(searchNumber);\n  const escaped = expected.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const bodyText = normalizeDigits(String(document.body?.innerText || \"\"));\n  const visibleIdentity = new RegExp(\n    `(?:^|[^0-9])${escaped}(?:[^0-9]|$)`,\n  ).test(bodyText);\n  if (visibleIdentity) return true;\n\n  const selectors = recordType === \"account\"\n    ? [\"#txtContract\", 'input[name=\"contract\"]']\n    : [\"#txtAccount\", 'input[name=\"account\"]'];\n  const inputIdentity = selectors.some((selector) =>\n    Array.from(document.querySelectorAll(selector)).some(\n      (field) => normalizeDigits(String(field.value || \"\").trim()) === expected,\n    ),\n  );\n  if (inputIdentity) return true;\n\n  // The contract and wallet pages do not consistently render the search number as text.\n  // Its exact query parameter (?contract= or ?account=), new task ID, and\n  // previous-amount guard together provide the identity check.\n  return (\n    isSupportedRecordType(recordType) &&\n    readPageSearchNumber(new URL(window.location.href), recordType) === expected\n  );\n}\n\nfunction readRejection() {\n  const bodyText = String(document.body?.innerText || \"\");\n  if (!bodyText.includes(\"The requested URL was rejected.\")) return null;\n\n  const match = bodyText.match(/Your support ID is:\\s*<?\\s*([0-9]+)/i);\n  return {\n    status: \"rejected\",\n    support_id: match ? match[1] : \"\",\n  };\n}\n\nfunction isVisible(element) {\n  const style = window.getComputedStyle(element);\n  const rectangle = element.getBoundingClientRect();\n  return (\n    style.display !== \"none\" &&\n    style.visibility !== \"hidden\" &&\n    style.opacity !== \"0\" &&\n    rectangle.width > 0 &&\n    rectangle.height > 0\n  );\n}\n\nfunction sameTask(activeTask, task) {\n  return Boolean(\n    activeTask &&\n      activeTask.task_id === task.task_id &&\n      activeTask.row_number === task.row_number &&\n      activeTask.record_type === task.record_type &&\n      activeTask.search_number === task.search_number,\n  );\n}\n\nfunction normalizeDigits(value) {\n  const source = \"٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹\";\n  const target = \"01234567890123456789\";\n  return Array.from(value, (character) => {\n    const index = source.indexOf(character);\n    return index === -1 ? character : target[index];\n  }).join(\"\");\n}\n\nfunction sendMessage(message) {\n  return chrome.runtime.sendMessage(message);\n}\n\nfunction isExtensionContextInvalidated(error) {\n  return (\n    !chrome.runtime?.id ||\n    String(error?.message || error).includes(\"Extension context invalidated\")\n  );\n}\n\nfunction delay(milliseconds) {\n  return new Promise((resolve) => setTimeout(resolve, milliseconds));\n}\n\nasync function waitUntilPageVisible() {\n  if (!document.hidden) return 0;\n  const hiddenAt = Date.now();\n  await new Promise((resolve) => {\n    const onVisibilityChange = () => {\n      if (document.hidden) return;\n      document.removeEventListener(\"visibilitychange\", onVisibilityChange);\n      resolve();\n    };\n    document.addEventListener(\"visibilitychange\", onVisibilityChange);\n  });\n  await delay(750);\n  return Date.now() - hiddenAt;\n}\n",
    "manifest.json": "{\n  \"manifest_version\": 3,\n  \"name\": \"Zain Account and Wallet Checker\",\n  \"version\": \"1.5.0\",\n  \"description\": \"Checks Zain account and wallet amounts in an Incognito Chrome tab with Ultra Bandwidth Saver.\",\n  \"incognito\": \"spanning\",\n  \"permissions\": [\n    \"activeTab\",\n    \"tabs\",\n    \"scripting\",\n    \"storage\",\n    \"webNavigation\",\n    \"declarativeNetRequest\"\n  ],\n  \"host_permissions\": [\n    \"https://app.sa.zain.com/*\",\n    \"http://127.0.0.1:8766/*\",\n    \"*://*.googletagmanager.com/*\",\n    \"*://*.google-analytics.com/*\",\n    \"*://*.doubleclick.net/*\",\n    \"*://*.fonts.gstatic.com/*\",\n    \"*://*.fonts.googleapis.com/*\",\n    \"*://*.facebook.net/*\",\n    \"*://*.hotjar.com/*\"\n  ],\n  \"declarative_net_request\": {\n    \"rule_resources\": [\n      {\n        \"id\": \"bandwidth_saver\",\n        \"enabled\": true,\n        \"path\": \"bandwidth_rules.json\"\n      }\n    ]\n  },\n  \"background\": {\n    \"service_worker\": \"service-worker.js\"\n  },\n  \"action\": {\n    \"default_title\": \"Zain Account and Wallet Checker\",\n    \"default_popup\": \"popup.html\"\n  },\n  \"content_scripts\": [\n    {\n      \"matches\": [\"https://app.sa.zain.com/*\"],\n      \"js\": [\"content.js\"],\n      \"run_at\": \"document_start\"\n    }\n  ]\n}\n",
    "popup.css": ":root {\n  color-scheme: light;\n  font-family: \"Segoe UI\", Arial, sans-serif;\n}\n\nbody {\n  margin: 0;\n  background: #f7f8fa;\n  color: #18212b;\n}\n\nmain {\n  width: 280px;\n  padding: 18px;\n}\n\nh1 {\n  margin: 0 0 12px;\n  font-size: 19px;\n}\n\n#status {\n  min-height: 42px;\n  margin: 0 0 14px;\n  line-height: 1.4;\n}\n\n.actions {\n  display: flex;\n  gap: 8px;\n}\n\nbutton {\n  flex: 1;\n  border: 0;\n  border-radius: 6px;\n  padding: 9px 12px;\n  background: #6d2677;\n  color: white;\n  cursor: pointer;\n  font-weight: 600;\n}\n\nbutton.secondary {\n  background: #69727d;\n}\n\n.hint {\n  margin: 13px 0 0;\n  color: #5f6974;\n  font-size: 12px;\n}\n",
    "popup.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Zain Account and Wallet Checker</title>\n    <link rel=\"stylesheet\" href=\"popup.css\" />\n  </head>\n  <body>\n    <main>\n      <h1>Zain Checker</h1>\n      <p id=\"status\">Ready.</p>\n      <div class=\"actions\">\n        <button id=\"start\" type=\"button\">Start</button>\n        <button id=\"stop\" type=\"button\" class=\"secondary\">Stop</button>\n      </div>\n      <p class=\"hint\">Run <code>py main.py</code> first.</p>\n    </main>\n    <script src=\"popup.js\"></script>\n  </body>\n</html>\n",
    "popup.js": "const statusElement = document.querySelector(\"#status\");\nconst startButton = document.querySelector(\"#start\");\nconst stopButton = document.querySelector(\"#stop\");\n\nstartButton.addEventListener(\"click\", async () => {\n  startButton.disabled = true;\n  statusElement.textContent = \"Starting...\";\n\n  try {\n    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\n    if (!Number.isInteger(tab?.id)) {\n      throw new Error(\"No active Chrome tab was found.\");\n    }\n\n    const response = await chrome.runtime.sendMessage({\n      type: \"start\",\n      tabId: tab.id,\n    });\n    if (response?.status !== \"started\") {\n      throw new Error(response?.message || \"Could not start.\");\n    }\n\n    statusElement.textContent = \"Started. Return to the Zain tab.\";\n    setTimeout(() => window.close(), 700);\n  } catch (error) {\n    statusElement.textContent = `Start failed: ${String(error?.message || error)}`;\n    startButton.disabled = false;\n  }\n});\n\nstopButton.addEventListener(\"click\", async () => {\n  await chrome.runtime.sendMessage({ type: \"stop\" });\n  await refreshStatus();\n});\n\nchrome.storage.onChanged.addListener((changes, areaName) => {\n  if (areaName === \"local\" && changes.zainCheckerStatus) {\n    statusElement.textContent = changes.zainCheckerStatus.newValue;\n  }\n});\n\nasync function refreshStatus() {\n  try {\n    const state = await chrome.storage.local.get(\"zainCheckerStatus\");\n    statusElement.textContent = state.zainCheckerStatus || \"Ready.\";\n  } catch {\n    statusElement.textContent = \"Ready.\";\n  }\n}\n\nrefreshStatus();\n",
    "service-worker.js": "const BRIDGE_URL = \"http://127.0.0.1:8766\";\nconst BRIDGE_TOKEN =\n  \"614e3c6720854e8cb09fa5bc41c609a184cc75123924446aa306f08f0efa085b\";\nconst ZAIN_PAYMENT_URL = \"https://app.sa.zain.com/ar/contract-payment\";\nconst ZAIN_QUICKPAY_URL = \"https://app.sa.zain.com/ar/quickpay\";\nlet incognitoHandoffPromise = null;\nconst SESSION_KEEPER_KEY = \"zainCheckerSessionKeeperWindowId\";\n\nasync function handleNavigationEvent(details) {\n  if (details.frameId !== 0) return;\n  const tab = await chrome.tabs.get(details.tabId).catch(() => null);\n  if (!(await isTargetTab(details.tabId, { tab }))) return;\n  try {\n    await chrome.tabs.update(details.tabId, { autoDiscardable: false });\n    await ensureContentScript(details.tabId);\n    await wakeTab(details.tabId);\n  } catch (error) {\n    await setStatus(\n      `Navigation error: ${String(error?.message || error)}`,\n    );\n  }\n}\n\nchrome.webNavigation.onCompleted.addListener(handleNavigationEvent, {\n  url: [{ hostEquals: \"app.sa.zain.com\", schemes: [\"https\"] }],\n});\nchrome.webNavigation.onHistoryStateUpdated.addListener(handleNavigationEvent, {\n  url: [{ hostEquals: \"app.sa.zain.com\", schemes: [\"https\"] }],\n});\n\nconst memoryStorage = {};\n\nasync function safeStorageGet(keys) {\n  const isArray = Array.isArray(keys);\n  const keyList = isArray ? keys : (typeof keys === \"string\" ? [keys] : Object.keys(keys || {}));\n  let result = {};\n\n  try {\n    result = await chrome.storage.local.get(keys);\n  } catch (error) {\n    console.warn(\"[ZainChecker:SW] Storage get failed, using memory fallback:\", error);\n    if (String(error?.message || error).includes(\"Corruption\")) {\n      try {\n        await chrome.storage.local.clear();\n      } catch {}\n    }\n  }\n\n  for (const k of keyList) {\n    if (result[k] === undefined && memoryStorage[k] !== undefined) {\n      result[k] = memoryStorage[k];\n    }\n  }\n  return result;\n}\n\nasync function safeStorageSet(items) {\n  if (!items || typeof items !== \"object\") return;\n  Object.assign(memoryStorage, items);\n\n  try {\n    await chrome.storage.local.set(items);\n  } catch (error) {\n    console.warn(\"[ZainChecker:SW] Storage set failed, retained in memory:\", error);\n    if (String(error?.message || error).includes(\"Corruption\")) {\n      try {\n        await chrome.storage.local.clear();\n      } catch {}\n    }\n  }\n}\n\nasync function safeStorageRemove(keys) {\n  const keyList = Array.isArray(keys) ? keys : [keys];\n  for (const k of keyList) {\n    delete memoryStorage[k];\n  }\n  try {\n    await chrome.storage.local.remove(keys);\n  } catch (error) {\n    console.warn(\"[ZainChecker:SW] Storage remove failed:\", error);\n  }\n}\n\nfunction isAllowedCheckerTab(sender) {\n  if (!sender) return false;\n  if (sender.tab?.incognito) return true;\n  const url = String(sender.tab?.url || sender.url || \"\");\n  if (url.startsWith(\"https://app.sa.zain.com/\")) return true;\n  if (Number.isInteger(sender.tab?.id)) return true;\n  return false;\n}\n\nchrome.runtime.onMessage.addListener((message, sender, sendResponse) => {\n  handleMessage(message, sender)\n    .then(sendResponse)\n    .catch(async (error) => {\n      const detail = String(error?.message || error);\n      console.error(\"[ZainChecker:SW] Message handler error for\", message?.type, detail, error?.stack);\n      try {\n        await setStatus(`Error: ${detail}`);\n      } catch (statusError) {\n        console.warn(\"[ZainChecker:SW] Could not write error status:\", statusError);\n      }\n      try {\n        sendResponse({ status: \"bridge_error\", message: detail });\n      } catch (respError) {\n        console.warn(\"[ZainChecker:SW] Could not send bridge_error response:\", respError);\n      }\n    });\n  return true;\n});\n\nasync function handleMessage(message, sender) {\n  console.log(\"[ZainChecker:SW] Message:\", message?.type, \"tabId:\", sender.tab?.id, \"incognito:\", sender.tab?.incognito, \"url:\", sender.url || sender.tab?.url);\n\n  if (message?.type === \"adopt_tab\") {\n    const tabId = sender.tab?.id;\n    if (Number.isInteger(tabId) && isAllowedCheckerTab(sender)) {\n      await safeStorageSet({\n        zainCheckerRunning: true,\n        zainCheckerTabId: tabId,\n      });\n      try {\n        const task = await fetchJson(`${BRIDGE_URL}/task`);\n        if (task?.status === \"check\") {\n          await ensureHandoffAcknowledged(task);\n        }\n      } catch {\n        // Non-fatal\n      }\n      await closeSessionKeeperWindow();\n      return { status: \"adopted\" };\n    }\n    return { status: \"ignored\" };\n  }\n\n  if (message?.type === \"auto_start\") {\n    const tabId = sender.tab?.id;\n    const windowId = sender.tab?.windowId;\n    if (!Number.isInteger(tabId)) {\n      return { status: \"ignored\", reason: \"no_tab_id\", sender_tab: sender.tab };\n    }\n    if (!isAllowedCheckerTab(sender)) {\n      return { status: \"ignored\", reason: \"not_allowed\", sender_tab: sender.tab, sender_url: sender.url };\n    }\n\n    let task;\n    try {\n      task = await fetchJson(`${BRIDGE_URL}/task`);\n    } catch {\n      return { status: \"bridge_offline\" };\n    }\n\n    if (task?.status !== \"check\") {\n      return { status: \"no_task\" };\n    }\n\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus: \"Closing other Incognito windows...\",\n      zainCheckerActiveTask: null,\n    });\n    if (Number.isInteger(windowId)) {\n      await closeIncognitoWindowsExcept(windowId);\n      await closeExtraTabsInWindow(windowId, tabId);\n    }\n    await safeStorageSet({\n      zainCheckerRunning: true,\n      zainCheckerTabId: tabId,\n      zainCheckerStatus: `Starting ${task.record_type} ${task.search_number} automatically...`,\n      zainCheckerActiveTask: {\n        task_id: task.task_id,\n        row_number: task.row_number,\n        record_type: task.record_type,\n        search_number: task.search_number,\n        stage: \"navigating\",\n        previous_website_amount: null,\n      },\n    });\n    await ensureHandoffAcknowledged(task);\n    await closeSessionKeeperWindow();\n    return { status: \"started\" };\n  }\n\n  if (message?.type === \"start\") {\n    const tabId = Number(message.tabId);\n    if (!Number.isInteger(tabId)) {\n      throw new Error(\"No active Chrome tab was found.\");\n    }\n\n    const tab = await chrome.tabs.get(tabId);\n    if (!tab.incognito) {\n      const task = await fetchJson(`${BRIDGE_URL}/task`);\n      if (task.status !== \"check\") {\n        throw new Error(\n          task.message || \"Python did not provide a record to check.\",\n        );\n      }\n      await runIncognitoHandoff(task);\n      return { status: \"started\" };\n    }\n\n    await safeStorageSet({\n      zainCheckerRunning: true,\n      zainCheckerTabId: tabId,\n      zainCheckerStatus: \"Starting...\",\n      zainCheckerActiveTask: null,\n    });\n\n    if (!String(tab.url || \"\").startsWith(\"https://app.sa.zain.com/\")) {\n      const task = await fetchJson(`${BRIDGE_URL}/task`);\n      if (task.status !== \"check\") {\n        throw new Error(task.message || \"Python did not provide a record to check.\");\n      }\n      await ensureHandoffAcknowledged(task);\n      await chrome.tabs.update(tabId, {\n        url: buildDirectUrl(task.record_type, task.search_number),\n      });\n    } else {\n      try {\n        const task = await fetchJson(`${BRIDGE_URL}/task`);\n        if (task?.status === \"check\") {\n          await ensureHandoffAcknowledged(task);\n        }\n      } catch {}\n      await ensureContentScript(tabId);\n      await wakeTab(tabId);\n    }\n    return { status: \"started\" };\n  }\n\n  if (message?.type === \"stop\") {\n    const state = await safeStorageGet(\"zainCheckerTabId\");\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus: \"Stopped.\",\n      zainCheckerActiveTask: null,\n    });\n    if (Number.isInteger(state.zainCheckerTabId)) {\n      await wakeTab(state.zainCheckerTabId);\n    }\n    return { status: \"stopped\" };\n  }\n\n  if (message?.type === \"navigate_task\") {\n    if (!(await isTargetTab(sender.tab?.id, sender))) {\n      console.log(\"[ZainChecker:SW] navigate_task rejected: not target tab\");\n      return { status: \"inactive\" };\n    }\n    const task = normalizeTask(message.task);\n    const tabId = sender.tab.id;\n    console.log(\"[ZainChecker:SW] navigate_task executing for search_number:\", task.search_number, \"reload:\", message.reload);\n    await safeStorageSet({\n      zainCheckerActiveTask: {\n        ...task,\n        stage: \"navigating\",\n        previous_website_amount: String(\n          message.previous_website_amount || \"\",\n        ),\n      },\n      zainCheckerStatus: `Navigating to ${task.record_type} ${task.search_number}...`,\n    });\n    const directUrl = buildDirectUrl(task.record_type, task.search_number);\n    const currentTab = await chrome.tabs.get(tabId).catch(() => null);\n    if (message.reload === true) {\n      console.log(\"[ZainChecker:SW] Reloading tabId:\", tabId);\n      await chrome.tabs.reload(tabId);\n    } else {\n      console.log(\"[ZainChecker:SW] Updating same tabId:\", tabId, \"to directUrl:\", directUrl);\n      await chrome.tabs.update(tabId, { url: directUrl, autoDiscardable: false });\n    }\n    return { status: \"navigating\" };\n  }\n\n  if (message?.type === \"poll_task\") {\n    if (!(await isTargetTab(sender.tab?.id, sender))) {\n      console.log(\"[ZainChecker:SW] poll_task rejected: isTargetTab returned false\");\n      return { status: \"inactive\" };\n    }\n\n    let response;\n    try {\n      response = await fetchJson(`${BRIDGE_URL}/task`);\n      console.log(\"[ZainChecker:SW] poll_task response from bridge:\", JSON.stringify(response));\n    } catch (error) {\n      const detail =\n        `Cannot connect to the Python bridge: ${String(error?.message || error)}`;\n      console.error(\"[ZainChecker:SW] poll_task bridge error:\", detail);\n      await setStatus(detail);\n      return { status: \"bridge_error\", message: detail };\n    }\n\n    if (response?.status === \"check\") {\n      await ensureHandoffAcknowledged(response);\n\n      const isService2Cycle =\n        response.cycle_mode === \"SERVICE_2\" ||\n        response.record_type === \"wallet\" ||\n        String(response.search_number || \"\").startsWith(\"2\");\n      const cycleId = Number(response.service_cycle_id || 0);\n      const stateCycle = await safeStorageGet(\"zainCheckerLastRefreshedCycleId\");\n      const lastRefreshedCycleId = Number(stateCycle.zainCheckerLastRefreshedCycleId || 0);\n\n      if (\n        isService2Cycle &&\n        cycleId > 0 &&\n        response.refresh_once === true &&\n        lastRefreshedCycleId !== cycleId\n      ) {\n        await safeStorageSet({ zainCheckerLastRefreshedCycleId: cycleId });\n        await acknowledgeCycleRefreshed(cycleId, response.task_id);\n        response.do_single_refresh = true;\n      } else {\n        response.do_single_refresh = false;\n      }\n    }\n\n    await updateStatusFromBridge(response);\n    return response;\n  }\n\n  if (message?.type === \"submit_result\") {\n    if (!(await isTargetTab(sender.tab?.id, sender))) {\n      console.log(\"[ZainChecker:SW] submit_result rejected: isTargetTab returned false\");\n      return { status: \"inactive\" };\n    }\n\n    console.log(\"[ZainChecker:SW] Submitting result:\", JSON.stringify(message.result));\n    const response = await fetchJson(`${BRIDGE_URL}/result`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(message.result),\n    });\n    console.log(\"[ZainChecker:SW] Submit response from bridge:\", JSON.stringify(response));\n    await updateStatusFromBridge(response);\n    return response;\n  }\n\n  return { status: \"ignored\" };\n}\n\nasync function fetchJson(url, options = {}) {\n  const headers = {\n    \"X-Zain-Bridge-Token\": BRIDGE_TOKEN,\n    ...(options.headers || {}),\n  };\n  const response = await fetch(url, {\n    cache: \"no-store\",\n    ...options,\n    headers,\n  });\n  const payload = await response.json();\n  if (!response.ok) {\n    throw new Error(payload.message || `Bridge returned HTTP ${response.status}.`);\n  }\n  return payload;\n}\n\nasync function isTargetTab(tabId, sender) {\n  const state = await safeStorageGet([\n    \"zainCheckerRunning\",\n    \"zainCheckerTabId\",\n  ]);\n  if (!state.zainCheckerRunning) {\n    console.log(\"[ZainChecker:SW] isTargetTab: false because zainCheckerRunning is false\");\n    return false;\n  }\n  if (!Number.isInteger(tabId)) {\n    console.log(\"[ZainChecker:SW] isTargetTab: false because tabId not integer:\", tabId);\n    return false;\n  }\n  if (tabId === state.zainCheckerTabId) {\n    return true;\n  }\n  if (isAllowedCheckerTab(sender)) {\n    await safeStorageSet({ zainCheckerTabId: tabId });\n    return true;\n  }\n  console.log(\"[ZainChecker:SW] isTargetTab: false for tabId:\", tabId, \"stateTabId:\", state.zainCheckerTabId);\n  return false;\n}\n\nasync function updateStatusFromBridge(response) {\n  if (response.status === \"check\") {\n    await setStatus(\n      `Checking ${response.sequence} of ${response.total}: ${response.search_number}`,\n    );\n    return;\n  }\n  if (response.status === \"waiting\") {\n    await setStatus(\n      `Waiting ${response.retry_after_seconds} second(s). ` +\n        `Checked ${response.checked ?? 0} of ${response.total ?? \"?\"}.`,\n    );\n    return;\n  }\n  if (response.status === \"recheck_mismatch\") {\n    await setStatus(\n      `Possible mismatch. Rechecking the same account in ` +\n        `${response.retry_after_seconds} second(s)...`,\n    );\n    return;\n  }\n  if (response.status === \"reload_mismatch\") {\n    await setStatus(\n      `Mismatch remained. Reloading the same account for one final check...`,\n    );\n    return;\n  }\n  if (response.status === \"retry_redirect\") {\n    await setStatus(\n      `The page did not settle on the requested record. Retrying the same ` +\n        `search number once...`,\n    );\n    return;\n  }\n  if (response.status === \"network_wait\") {\n    await setStatus(\n      `Zain requests paused for safety. Waiting for confirmation in the dashboard. ` +\n        `Search number ${response.search_number} was not counted.`,\n    );\n    return;\n  }\n  if (response.status === \"complete\") {\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus: `Complete: ${response.total} account(s).`,\n      zainCheckerActiveTask: null,\n    });\n    return;\n  }\n  if (response.status === \"open_incognito\") {\n    await runIncognitoHandoff(response);\n    return;\n  }\n  if (response.status === \"incognito_failed\") {\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus: \"Closing the rejected Incognito session...\",\n      zainCheckerActiveTask: null,\n    });\n    await closeAllIncognitoWindows();\n    await safeStorageSet({\n      zainCheckerStatus: `Error: ${response.message}`,\n    });\n    return;\n  }\n  if (response.status === \"error\") {\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus: `Error: ${response.message}`,\n    });\n  }\n}\n\nasync function setStatus(status) {\n  try {\n    await safeStorageSet({ zainCheckerStatus: status });\n  } catch (error) {\n    console.warn(\"[ZainChecker:SW] setStatus non-fatal error:\", error);\n  }\n}\n\nasync function runIncognitoHandoff(response) {\n  const handoff =\n    incognitoHandoffPromise || openFreshIncognitoChecker(response);\n  incognitoHandoffPromise = handoff;\n  try {\n    await handoff;\n  } finally {\n    if (incognitoHandoffPromise === handoff) {\n      incognitoHandoffPromise = null;\n    }\n  }\n}\n\nasync function openFreshIncognitoChecker(response) {\n  const taskId = String(response.task_id || \"\").trim();\n  const rowNumber = Number(response.row_number);\n  const recordType = String(response.record_type || \"\").trim();\n  const searchNumber = String(response.search_number || \"\").trim();\n  if (\n    !taskId ||\n    !Number.isInteger(rowNumber) ||\n    rowNumber <= 0 ||\n    !isSupportedRecordType(recordType) ||\n    !/^\\d+$/.test(searchNumber)\n  ) {\n    throw new Error(\"Python returned an invalid record for Incognito retry.\");\n  }\n\n  const incognitoAllowed = await new Promise((resolve) => {\n    chrome.extension.isAllowedIncognitoAccess(resolve);\n  });\n  if (!incognitoAllowed) {\n    await safeStorageSet({\n      zainCheckerRunning: false,\n      zainCheckerStatus:\n        \"Enable Allow in Incognito in the extension Details page, then start again.\",\n      zainCheckerActiveTask: null,\n    });\n    throw new Error(\n      \"Automatic Incognito access is disabled. Open chrome://extensions, \" +\n        \"select Zain Account and Wallet Checker > Details, and enable Allow in Incognito.\",\n    );\n  }\n\n  await ensureSessionKeeperWindow();\n  await safeStorageSet({\n    zainCheckerRunning: false,\n    zainCheckerStatus: \"Closing all existing Incognito windows...\",\n    zainCheckerActiveTask: null,\n  });\n  await closeAllIncognitoWindows();\n\n  await safeStorageSet({\n    zainCheckerRunning: false,\n    zainCheckerStatus: `Opening ${recordType} ${searchNumber} in a new Incognito window...`,\n    zainCheckerActiveTask: null,\n  });\n\n  const directUrl = buildDirectUrl(recordType, searchNumber);\n  const createdWindow = await chrome.windows.create({\n    url: directUrl,\n    incognito: true,\n    focused: true,\n  });\n  let createdTabs = createdWindow?.tabs || [];\n  if (createdTabs.length === 0 && Number.isInteger(createdWindow?.id)) {\n    createdTabs = await chrome.tabs.query({ windowId: createdWindow.id });\n  }\n\n  const tabId = createdTabs[0]?.id;\n  if (!Number.isInteger(tabId)) {\n    throw new Error(\"Chrome opened Incognito but did not return its Zain tab.\");\n  }\n\n  if (Number.isInteger(createdWindow?.id)) {\n    await closeExtraTabsInWindow(createdWindow.id, tabId);\n  }\n\n  await safeStorageSet({\n    zainCheckerRunning: true,\n    zainCheckerTabId: tabId,\n    zainCheckerStatus: `Opening ${recordType} ${searchNumber} in 1 fresh Incognito tab...`,\n    zainCheckerActiveTask: {\n      task_id: taskId,\n      row_number: rowNumber,\n      record_type: recordType,\n      search_number: searchNumber,\n      stage: \"navigating\",\n      previous_website_amount: null,\n    },\n  });\n  await chrome.tabs.update(tabId, { autoDiscardable: false });\n  setTimeout(() => {\n    closeSessionKeeperWindow().catch(() => {});\n  }, 2500);\n}\n\nasync function closeAllIncognitoWindows() {\n  await closeIncognitoWindowsExcept(null);\n}\n\nasync function closeExtraTabsInWindow(windowId, keptTabId) {\n  if (!Number.isInteger(windowId) || !Number.isInteger(keptTabId)) return;\n  try {\n    const tabsInWin = await chrome.tabs.query({ windowId });\n    const extraTabIds = tabsInWin\n      .filter((t) => Number.isInteger(t.id) && t.id !== keptTabId)\n      .map((t) => t.id);\n    if (extraTabIds.length > 0) {\n      await chrome.tabs.remove(extraTabIds);\n    }\n  } catch {}\n}\n\nasync function ensureSessionKeeperWindow() {\n  const state = await safeStorageGet(SESSION_KEEPER_KEY);\n  const existingId = state[SESSION_KEEPER_KEY];\n  if (Number.isInteger(existingId)) {\n    try {\n      const existingWindow = await chrome.windows.get(existingId);\n      if (!existingWindow.incognito) return existingId;\n    } catch {\n      // The stored keeper no longer exists; create a replacement below.\n    }\n  }\n\n  const keeper = await chrome.windows.create({\n    url: \"about:blank\",\n    incognito: false,\n    focused: false,\n    state: \"minimized\",\n    type: \"normal\",\n  });\n  if (!Number.isInteger(keeper?.id)) {\n    throw new Error(\"Chrome could not create the temporary session keeper window.\");\n  }\n  await safeStorageSet({ [SESSION_KEEPER_KEY]: keeper.id });\n  return keeper.id;\n}\n\nasync function closeSessionKeeperWindow() {\n  const state = await safeStorageGet(SESSION_KEEPER_KEY);\n  const keeperId = state[SESSION_KEEPER_KEY];\n  await safeStorageRemove(SESSION_KEEPER_KEY);\n  if (!Number.isInteger(keeperId)) return;\n  try {\n    await chrome.windows.remove(keeperId);\n  } catch {\n    // It was already closed manually or by Chrome.\n  }\n}\n\nasync function closeIncognitoWindowsExcept(keptWindowId) {\n  for (let attempt = 1; attempt <= 10; attempt += 1) {\n    // 1. Explicitly close all Incognito tabs first\n    try {\n      const allTabs = await chrome.tabs.query({});\n      const incognitoTabIds = allTabs\n        .filter(\n          (tab) =>\n            tab.incognito &&\n            Number.isInteger(tab.id) &&\n            tab.windowId !== keptWindowId,\n        )\n        .map((tab) => tab.id);\n      if (incognitoTabIds.length > 0) {\n        await chrome.tabs.remove(incognitoTabIds).catch(() => {});\n      }\n    } catch {}\n\n    // 2. Close all Incognito windows except keptWindowId\n    const existingWindows = await chrome.windows.getAll();\n    const incognitoWindowIds = existingWindows\n      .filter(\n        (existingWindow) =>\n          existingWindow.incognito &&\n          Number.isInteger(existingWindow.id) &&\n          existingWindow.id !== keptWindowId,\n      )\n      .map((existingWindow) => existingWindow.id);\n    if (incognitoWindowIds.length === 0) {\n      // Extra settle delay after confirming all Incognito tabs and windows are closed\n      // so Chrome completely flushes the Incognito profile memory/cookies.\n      await new Promise((resolve) => setTimeout(resolve, 350));\n      return;\n    }\n\n    await Promise.allSettled(\n      incognitoWindowIds.map((windowId) => chrome.windows.remove(windowId)),\n    );\n    await new Promise((resolve) => setTimeout(resolve, 300));\n  }\n\n  const remainingWindows = await chrome.windows.getAll();\n  if (\n    remainingWindows.some(\n      (existingWindow) =>\n        existingWindow.incognito && existingWindow.id !== keptWindowId,\n    )\n  ) {\n    console.warn(\"Some older Incognito windows may still be closing.\");\n  }\n}\n\nasync function wakeTab(tabId) {\n  try {\n    await chrome.tabs.sendMessage(tabId, { type: \"wake\" });\n  } catch {\n    // The content script starts automatically after a Zain page loads.\n  }\n}\n\nasync function ensureContentScript(tabId) {\n  try {\n    const response = await chrome.tabs.sendMessage(tabId, { type: \"ping\" });\n    if (response?.status === \"ready\") return;\n  } catch {\n    // Existing tabs do not receive a newly installed content script.\n  }\n\n  await chrome.scripting.executeScript({\n    target: { tabId },\n    files: [\"content.js\"],\n  });\n}\n\nfunction buildDirectUrl(recordType, searchNumber) {\n  const encoded = encodeURIComponent(searchNumber);\n  if (recordType === \"account\") {\n    return `${ZAIN_PAYMENT_URL}?contract=${encoded}`;\n  }\n  if (recordType === \"wallet\") {\n    return `${ZAIN_QUICKPAY_URL}?account=${encoded}`;\n  }\n  throw new Error(\"Python returned an unsupported record type.\");\n}\n\nfunction isSupportedRecordType(recordType) {\n  return recordType === \"account\" || recordType === \"wallet\";\n}\n\nlet handoffAcknowledgedTaskId = null;\n\nasync function acknowledgeHandoff(task) {\n  const response = await fetchJson(`${BRIDGE_URL}/handoff-ready`, {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(task),\n  });\n  if (\n    response.status !== \"handoff_acknowledged\" &&\n    response.status !== \"complete\"\n  ) {\n    throw new Error(\"Python rejected the Incognito handoff acknowledgement.\");\n  }\n}\n\nasync function acknowledgeCycleRefreshed(serviceCycleId, taskId) {\n  try {\n    await fetchJson(`${BRIDGE_URL}/cycle-refreshed`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({\n        service_cycle_id: serviceCycleId,\n        task_id: taskId || \"\",\n      }),\n    });\n  } catch (error) {\n    console.warn(\"[ZainChecker:SW] Non-fatal error acknowledging cycle refresh:\", error);\n  }\n}\n\nasync function ensureHandoffAcknowledged(task) {\n  if (!task || task.status !== \"check\" || !task.task_id) return;\n  if (handoffAcknowledgedTaskId === task.task_id) return;\n  try {\n    await acknowledgeHandoff({\n      task_id: task.task_id,\n      row_number: task.row_number,\n      record_type: task.record_type,\n      search_number: task.search_number,\n    });\n    handoffAcknowledgedTaskId = task.task_id;\n  } catch (error) {\n    // Non-fatal if already acknowledged or offline\n  }\n}\n\nfunction normalizeTask(task) {\n  const normalized = {\n    task_id: String(task?.task_id || \"\").trim(),\n    row_number: Number(task?.row_number),\n    record_type: String(task?.record_type || \"\").trim(),\n    search_number: String(task?.search_number || \"\").trim(),\n  };\n  if (\n    !normalized.task_id ||\n    !Number.isInteger(normalized.row_number) ||\n    normalized.row_number <= 0 ||\n    !isSupportedRecordType(normalized.record_type) ||\n    !/^\\d+$/.test(normalized.search_number)\n  ) {\n    throw new Error(\"Python returned an invalid navigation task.\");\n  }\n  return normalized;\n}\n"
}
